-- Tables the financial chain reads and writes. Generated from the PRODUCTION catalog on 10/11/2026
-- (columns, types, defaults, primary keys and unique constraints). Foreign keys, RLS policies and
-- triggers are left out on purpose: these tests exercise the SQL functions, run as the table owner.
-- profiles is trimmed to the columns the chain uses.
create table public.profiles (id uuid not null default gen_random_uuid(), user_id uuid not null unique, nickname text, cpf text, tax_cnpj text, pix_merchant_name text, avatar_url text, verificado boolean not null default false, ranking_hidden boolean default false, ranking_oculto boolean default false, primary key (id));
create table public.auto_detected_sales (id uuid not null default gen_random_uuid(), user_id uuid not null, bank_connection_id uuid, transaction_id text not null, amount numeric not null, description text, transaction_date date not null, status text not null default 'pending'::text, daily_sale_id uuid, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), is_pix boolean, transacted_at timestamp with time zone, own_transfer boolean not null default false, pagador_nome text, pagador_doc text, PRIMARY KEY (id), UNIQUE (transaction_id));
create table public.banco_entradas_revisao (transaction_id text not null, user_id uuid not null, amount numeric not null, motivo text not null, status text not null default 'pendente'::text, criado_em timestamp with time zone not null default now(), decidido_em timestamp with time zone, decidido_por uuid, PRIMARY KEY (transaction_id));
create table public.banco_excesso_ok (user_id uuid not null, dia date not null, aprovado_em timestamp with time zone not null default now(), obs text, PRIMARY KEY (user_id, dia));
create table public.bank_connections (id uuid not null default gen_random_uuid(), user_id uuid not null, item_id text not null, institution_name text not null, institution_logo text, status text not null default 'connected'::text, last_synced_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), pluggy_pedido_em timestamp with time zone, papel text, papel_desde timestamp with time zone, papel_trocado_em timestamp with time zone, historico_lido_em timestamp with time zone, leituras_dia date, leituras_qtd integer not null default 0, pedidos_mes text, pedidos_mes_qtd integer not null default 0, pedidos_dia date, pedidos_dia_qtd integer not null default 0, dono_nome text, dono_doc text, papel_auto boolean not null default false, pausado_em timestamp with time zone, leitura_ok_em timestamp with time zone, UNIQUE (item_id), PRIMARY KEY (id));
create table public.bank_saldos (conta_id text not null, user_id uuid not null, bank_connection_id uuid, banco text, nome text, saldo numeric, atualizado_em timestamp with time zone not null default now(), cheque_limite numeric, cheque_usado numeric, PRIMARY KEY (conta_id));
create table public.challenge_sessions (id uuid not null default gen_random_uuid(), user_id uuid not null, date date not null default CURRENT_DATE, status text not null default 'active'::text, daily_goal numeric not null, total_blocks integer not null default 0, current_block_index integer not null default 0, total_sold numeric not null default 0, started_at timestamp with time zone not null default now(), ended_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), worked_minutes integer, distance_meters numeric not null default 0, paused_seconds integer not null default 0, sinal_osm_id bigint, sinal_rating text, sinal_duracao text, sinal_compartilha boolean not null default false, sinal_lat double precision, sinal_lng double precision, origem text, PRIMARY KEY (id), UNIQUE (user_id, date));
create table public.daily_goal_plans (id uuid not null default gen_random_uuid(), user_id uuid not null, date date not null default CURRENT_DATE, daily_goal numeric not null, work_hours integer not null, mood text not null, hourly_goal numeric not null, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id), UNIQUE (user_id, date));
create table public.daily_sales (id uuid not null default gen_random_uuid(), user_id uuid not null, date date not null default CURRENT_DATE, total_profit numeric default 0, total_debt numeric default 0, unpaid_sales integer default 0, cash_sales numeric default 0, pix_sales numeric default 0, card_sales numeric default 0, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), cost numeric default 0, reinvestment numeric default 0, tip_sales numeric default 0, transport_cost numeric default 0, food_cost numeric default 0, unpaid_units integer not null default 0, units_carried integer not null default 0, pix_manual boolean not null default false, dinheiro_informado numeric, PRIMARY KEY (id));
create unique index daily_sales_user_date_unique on public.daily_sales (user_id, date);
create table public.defcon_sales (id uuid not null default gen_random_uuid(), user_id uuid not null, session_id uuid, block_index integer, amount numeric not null default 0, method text, late boolean not null default false, created_at timestamp with time zone not null default now(), product_id uuid, qty numeric not null default 1, variant_id uuid, PRIMARY KEY (id));
create table public.extrato_lancamentos (id uuid not null default gen_random_uuid(), user_id uuid not null, arquivo_id uuid, data date not null, hora time without time zone, descricao text not null, descricao_norm text not null, comerciante text, valor numeric(12,2) not null, tipo text not null, categoria text not null default 'nao_identificado'::text, esfera text not null default 'pessoal'::text, confianca text not null default 'ia'::text, banco text, criado_em timestamp with time zone not null default now(), chave text, movimento text not null default 'normal'::text, par_id uuid, recorrente boolean not null default false, pessoa text, origem text not null default 'arquivo'::text, pluggy_tx_id text, do_cartao boolean not null default false, categoria_fixa boolean not null default false, fora_analise boolean not null default false, apelido text, PRIMARY KEY (id), UNIQUE (user_id, data, valor, tipo, descricao_norm));
create table public.extrato_uploads (id uuid not null default gen_random_uuid(), user_id uuid not null, dia date not null, tipo text not null, total_verificado numeric not null default 0, qtd_vendas integer not null default 0, total_ignorado numeric not null default 0, vendas jsonb not null default '[]'::jsonb, motor text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), edicao_suspeita boolean not null default false, motivo_edicao text, PRIMARY KEY (id), UNIQUE (user_id, dia, tipo));
create table public.hourly_goal_blocks (id uuid not null default gen_random_uuid(), plan_id uuid not null, user_id uuid not null, hour_index integer not null, hour_label text not null, target_amount numeric not null, achieved_amount numeric not null default 0, is_completed boolean not null default false, manual_adjustment numeric default 0, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), valor_dinheiro numeric default 0, valor_cartao numeric default 0, valor_pix numeric default 0, valor_calote numeric default 0, timer_status text default 'idle'::text, timer_started_at timestamp with time zone, timer_paused_at timestamp with time zone, timer_elapsed_seconds integer default 0, approaches_count integer not null default 0, valor_gorjeta numeric default 0, lunch_ends_at timestamp with time zone, PRIMARY KEY (id), UNIQUE (plan_id, hour_index));
create table public.leaderboard_stats (id uuid not null default gen_random_uuid(), user_id uuid not null, nome_usuario text, avatar_url text, mes_referencia text not null, faturamento_total_mes numeric not null default 0, dias_trabalhados_mes integer not null default 0, constancia_maior_streak integer not null default 0, constancia_streak_atual integer not null default 0, posicao_faturamento integer, posicao_constancia integer, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), faturamento_pix_mes numeric not null default 0, PRIMARY KEY (id), UNIQUE (user_id, mes_referencia));
create table public.open_finance_contas_proprias (user_id uuid not null, termo text not null, criado_em timestamp with time zone not null default now(), PRIMARY KEY (user_id, termo));
