create table public.premio_fechamento (tipo text not null, inicio date not null, fim date not null, user_id uuid not null, posicao integer not null, valor numeric not null, dias integer not null default 0, verificado boolean not null default false, leva_premio boolean not null default false, congelado_em timestamp with time zone not null default now(), status text not null default 'homologado'::text, pendencias jsonb not null default '[]'::jsonb, homologado_em timestamp with time zone, PRIMARY KEY (tipo, inicio, user_id));
create table public.ranking_dia_cache (user_id uuid not null, dia date not null, valor numeric not null default 0, pelo_banco boolean not null default false, atualizado_em timestamp with time zone not null default now(), PRIMARY KEY (user_id, dia));
-- Access rules copied from production for the one table whose exposure is under test (F-17).
alter table public.premio_fechamento enable row level security;
create policy premio_fechamento_ler on public.premio_fechamento for select to authenticated using (true);
grant select on public.premio_fechamento to anon, authenticated;
